#include "driver.hpp"
#include "format.hpp"

int main(int argc, char** argv)
{
	blitz::tools::driver tool;
	tool.name         = "blitz-format";
	tool.version      = BLITZLLVM_VERSION;
	tool.summary      = "formats BlitzBasic, Blitz3D and BlitzPlus source code";
	tool.config_names = { ".blitz-format", "blitz-format.json" };

	tool.options_help = "Settings:\n";
	for (auto const& info : blitz::format::option_list()) {
		tool.options_help += std::string("  ") + info.name + " = " + info.values + "  (default " + info.default_text + ")\n      " + info.description + "\n";
	}

	auto build = [](blitz::tools::settings const& values) {
		blitz::format::options o;
		for (auto const& [key, value] : values) {
			std::string error;
			if (!blitz::format::set_option(o, key, value, error)) {
				throw std::runtime_error(error);
			}
		}
		return o;
	};
	tool.process      = [build](std::string const& text, blitz::tools::settings const& values, std::string const&) { return blitz::format::format_source(text, build(values)); };
	tool.print_config = [build](blitz::tools::settings const& values) { return blitz::format::to_config(build(values)); };
	try {
		return blitz::tools::run(tool, argc, argv);
	} catch (std::exception const& ex) {
		fprintf(stderr, "blitz-format: %s\n", ex.what());
		return 2;
	}
}
